14	import jakarta.persistence.OneToMany;
15	import jakarta.persistence.OrderBy;
16	import jakarta.persistence.Table;
17	import java.math.BigDecimal;
18	import java.math.RoundingMode;
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.List;
22	import java.util.Optional;
23	import java.util.function.UnaryOperator;
24	import net.officefloor.hq.app.project.Project;
25	
26	/**
27	 * An invoice raised against a project. It is built from line items, and can take several discounts off
28	 * their sum before tax, each either a percentage or a flat amount (the percentages each taking their share
29	 * of the subtotal first (a percentage capped at a maximum never taking off more than that), then the flat amounts, shared across the lines in proportion to what each
30	 * charges; together never more than the subtotal), then add a percentage sales tax on what is left of the taxable lines only
31	 * (tax-free lines are never taxed), and optionally a second tax (a levy) worked out on the same taxable base;
32	 * its stored amount is always that subtotal less the discount plus the tax plus the levy, plus any flat
33	 * surcharge (such as a handling fee), which is added on last and is never taxed.
34	 * <p>
35	 * Every figure is worked out line by line: each line is rounded to the cent first and the rounded lines
36	 * are then added up, and the tax and levy are likewise worked out and rounded on each taxable line before
37	 * being added up, so the totals are sums of rounded lines rather than a rounded sum.
38	 * <p>
39	 * A tax-inclusive invoice (for a client whose prices already include tax) instead works the tax and
40	 * levy back out of the taxable lines after the discount: they are inside the price, so its amount is
41	 * just the subtotal less the discount (plus any surcharge), and the taxable base is what is left once they are taken out.
42	 * <p>
43	 * A tax-exempt invoice (for a tax-exempt client) has no taxable lines at all: it carries no tax or levy
44	 * whatever its lines or rates say, so its amount is the subtotal less the discount (plus any surcharge).
45	 */
46	@Entity
47	@Table(name = "invoice")
48	public class Invoice {
49	
50	    @Id
51	    @GeneratedValue(strategy = GenerationType.IDENTITY)
52	    private Long id;
53	
54	    @ManyToOne(fetch = FetchType.LAZY, optional = false)
55	    @JoinColumn(name = "project_id", nullable = false)
56	    private Project project;
57	
58	    @Column(nullable = false, precision = 12, scale = 2)
59	    private BigDecimal amount = BigDecimal.ZERO.setScale(2);
60	
61	    @Column(name = "tax_pct", nullable = false, precision = 5, scale = 2)
62	    private BigDecimal taxPct = BigDecimal.ZERO.setScale(2);
63	
64	    @Column(name = "levy_pct", nullable = false, precision = 5, scale = 2)
65	    private BigDecimal levyPct = BigDecimal.ZERO.setScale(2);
66	
67	    /** A flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
68	    @Column(nullable = false, precision = 12, scale = 2)
69	    private BigDecimal surcharge = BigDecimal.ZERO.setScale(2);
70	
71	    /** Whether the prices already include the tax and levy, so they are backed out rather than added on. */
72	    @Column(name = "tax_inclusive", nullable = false)
73	    private boolean taxInclusive;
74	
75	    /** Whether the invoice is for a tax-exempt client, so it carries no tax or levy whatever its lines say. */
76	    @Column(name = "tax_exempt", nullable = false)
77	    private boolean taxExempt;
78	
79	    /** The percentage taken off what is owed when paid early; zero when no early-payment discount is offered. */
80	    @Column(name = "early_payment_pct", nullable = false, precision = 5, scale = 2)
81	    private BigDecimal earlyPaymentPct = BigDecimal.ZERO.setScale(2);
82	
83	    /** How many days after being issued the invoice must be paid within to get the early-payment discount. */
84	    @Column(name = "early_payment_days", nullable = false)
85	    private int earlyPaymentDays;
86	
87	    @Enumerated(EnumType.STRING)
88	    @Column(nullable = false, length = 16)
89	    private InvoiceStatus status = InvoiceStatus.DRAFT;
90	
91	    @Column(name = "issued_date", nullable = false)
92	    private LocalDate issuedDate;
93	
94	    @Column(name = "due_date", nullable = false)
95	    private LocalDate dueDate;
96	
97	    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
98	    @OrderBy("id")
99	    private List<InvoiceLineItem> lineItems = new ArrayList<>();
100	
101	    /** The discounts taken off the subtotal before tax, in the order they were added. */
102	    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
103	    @OrderBy("id")
104	    private List<InvoiceDiscount> discounts = new ArrayList<>();
105	
106	    protected Invoice() {
107	    }
108	
109	    public Invoice(Project project, LocalDate issuedDate, LocalDate dueDate) {
110	        this.project = project;
111	        this.issuedDate = issuedDate;
112	        this.dueDate = dueDate;
113	        this.taxInclusive = project.getClient().isTaxInclusive();
114	        this.taxExempt = project.getClient().isTaxExempt();
115	    }
116	
117	    public Long getId() {
118	        return id;
119	    }
120	
121	    public Project getProject() {
122	        return project;
123	    }
124	
125	    public BigDecimal getAmount() {
126	        return amount;
127	    }
128	
129	    /**
130	     * The total before tax: the amount owed less the sales tax and levy, whether they were added on or
131	     * are included in the prices.
132	     */
133	    public BigDecimal getTotalExTax() {
134	        return amount.subtract(getTax()).subtract(getLevy());
135	    }
136	
137	    /**
138	     * The overall tax rate that actually ended up on the invoice: the sales tax and levy together as a
139	     * percentage of the total before tax, to two decimal places. It is below the headline rates when some
140	     * lines are tax-free, and zero when there is nothing before tax to charge it on.
141	     */
142	    public BigDecimal getEffectiveTaxPct() {
143	        BigDecimal totalExTax = getTotalExTax();
144	        if (totalExTax.signum() == 0) {
145	            return BigDecimal.ZERO.setScale(2);
146	        }
147	        return getTax().add(getLevy()).multiply(BigDecimal.valueOf(100)).divide(totalExTax, 2, RoundingMode.HALF_UP);
148	    }
149	
150	    /** The discounts on this invoice, in the order they were added. */
151	    public List<InvoiceDiscount> getDiscounts() {
152	        return List.copyOf(discounts);
153	    }
154	
155	    /**
156	     * The percentages taken off the subtotal, added up (never more than 100); zero when there is no
157	     * percentage discount.
158	     */
159	    public BigDecimal getDiscountPct() {
160	        return discounts.stream().map(InvoiceDiscount::getDiscountPct).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
161	                .min(BigDecimal.valueOf(100).setScale(2));
162	    }
163	
164	    /** The flat amounts asked to be taken off the subtotal, added up; zero when there is no flat discount. */
165	    public BigDecimal getDiscountAmount() {
166	        return discounts.stream().map(InvoiceDiscount::getDiscountAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
167	    }
168	
169	    /**
170	     * How much one of this invoice's discounts actually takes off the subtotal, to the cent. The
171	     * percentages are taken first, each its share of the subtotal (never more than its cap, if it has
172	     * one), then the flat amounts in the order they were added; none takes off more than is left after
173	     * those before it.
174	     */
175	    public BigDecimal discountTakenBy(InvoiceDiscount discount) {
176	        BigDecimal subtotal = getSubtotal();
177	        BigDecimal left = subtotal;
178	        for (InvoiceDiscount d : discountsInOrderTaken()) {
179	            BigDecimal wanted = d.isPercentage() ? percentWanted(subtotal, d) : d.getDiscountAmount();
180	            BigDecimal taken = wanted.min(left.max(BigDecimal.ZERO.setScale(2)));
181	            if (d == discount) {
182	                return taken;
183	            }
184	            left = left.subtract(taken);
185	        }
186	        return BigDecimal.ZERO.setScale(2);
187	    }
188	
189	    /** What a percentage discount asks to take off the subtotal: its share, never more than its cap. */
190	    private static BigDecimal percentWanted(BigDecimal subtotal, InvoiceDiscount discount) {
191	        BigDecimal share = percentOf(subtotal, discount.getDiscountPct());
192	        return isCappedAt(subtotal, discount) ? share.min(discount.getDiscountCap()) : share;
193	    }
194	
195	    /** Whether a discount's cap limits what it takes off the given subtotal. */
196	    private static boolean isCappedAt(BigDecimal subtotal, InvoiceDiscount discount) {
197	        return discount.getDiscountCap() != null
198	                && percentOf(subtotal, discount.getDiscountPct()).compareTo(discount.getDiscountCap()) > 0;
199	    }
200	
201	    /** The percentage discounts first, then the flat ones, each in the order they were added. */
202	    private List<InvoiceDiscount> discountsInOrderTaken() {
203	        List<InvoiceDiscount> ordered = new ArrayList<>(discounts.stream().filter(InvoiceDiscount::isPercentage).toList());
204	        ordered.addAll(discounts.stream().filter(d -> !d.isPercentage()).toList());
205	        return ordered;
206	    }
207	
208	    /**
209	     * What the line items add up to, before the invoice's discount: the sum of each line after its own
210	     * discount, rounded to the cent.
211	     */
212	    public BigDecimal getSubtotal() {
213	        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
214	    }
215	
216	    /** How much the discounts take off the subtotal together (what each takes off, added up), to the cent. */
217	    public BigDecimal getDiscount() {
218	        return discounts.stream().map(this::discountTakenBy).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
219	    }
220	
221	    /** The sales tax percentage added after the discount; zero when there is no tax. */
222	    public BigDecimal getTaxPct() {
223	        return taxPct;
224	    }
225	
226	    /** Whether the prices already include the tax and levy, so they are worked back out rather than added on. */
227	    public boolean isTaxInclusive() {
228	        return taxInclusive;
229	    }
230	
231	    /** Whether the invoice is for a tax-exempt client, so none of its lines are taxed. */
232	    public boolean isTaxExempt() {
233	        return taxExempt;
234	    }
235	
236	    /**
237	     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
238	     * taken off them, to the cent. On a tax-inclusive invoice that is what is left of them once the tax
239	     * and levy inside them are taken out.
240	     */
241	    public BigDecimal getTaxableBase() {
242	        BigDecimal gross = getDiscountedTaxable();
243	        return taxInclusive ? gross.subtract(getTax()).subtract(getLevy()) : gross;
244	    }
245	
246	    /**
247	     * How much sales tax is added on the taxable base (or is inside it, when tax-inclusive): the tax on
248	     * each taxable line rounded to the cent, added up.
249	     */
250	    public BigDecimal getTax() {
251	        return sumOverTaxableLines(this::taxOn);
252	    }
253	
254	    /** The levy (second tax) percentage added on top of the sales tax; zero when there is no levy. */
255	    public BigDecimal getLevyPct() {
256	        return levyPct;
257	    }
258	
259	    /**
260	     * How much levy is added on the taxable base (or is inside it, when tax-inclusive): the levy on each
261	     * taxable line rounded to the cent, added up.
262	     */
263	    public BigDecimal getLevy() {
264	        return sumOverTaxableLines(this::levyOn);
265	    }
266	
267	    /** The flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
268	    public BigDecimal getSurcharge() {
269	        return surcharge;
270	    }
271	
272	    /** The taxable lines (leaving out tax-free ones), each less the discount taken off it, added up. */
273	    private BigDecimal getDiscountedTaxable() {
274	        return sumOverTaxableLines(line -> line);
275	    }
276	
277	    /**
278	     * Works a figure out on each taxable line after its discount, to the cent, and adds them up. A
279	     * tax-exempt invoice has no taxable lines.
280	     */
281	    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
282	        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
283	                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
284	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
285	    }
286	
287	    /**
288	     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
289	     * divided in proportion to the sales tax and levy rates it includes (e.g. 20% tax in 120 is 20).
290	     */
291	    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
292	        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct).add(levyPct);
293	        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
294	    }
295	
296	    /** The percentage taken off what is owed when paid early; zero when none is offered. */
297	    public BigDecimal getEarlyPaymentPct() {
298	        return earlyPaymentPct;
299	    }
300	
301	    /** How many days after being issued the invoice must be paid within to get the early-payment discount. */
302	    public int getEarlyPaymentDays() {
303	        return earlyPaymentDays;
304	    }
305	
306	    /** Whether an early-payment discount is offered: a percentage off when paid within some days. */
307	    public boolean offersEarlyPayment() {
308	        return earlyPaymentPct.signum() > 0 && earlyPaymentDays > 0;
309	    }
310	
311	    /** The last day the invoice can be paid to get the early-payment discount; null when none is offered. */
312	    public LocalDate getEarlyPaymentBy() {
313	        return offersEarlyPayment() ? issuedDate.plusDays(earlyPaymentDays) : null;
314	    }
315	
316	    /**
317	     * The reduced amount to pay when settling early: the amount less the early-payment percentage of it,
318	     * to the cent; null when no early-payment discount is offered.
319	     */
320	    public BigDecimal getEarlyPaymentAmount() {
321	        return offersEarlyPayment() ? amount.subtract(percentOf(amount, earlyPaymentPct)) : null;
322	    }
323	
324	    public InvoiceStatus getStatus() {
325	        return status;
326	    }
327	
328	    public LocalDate getIssuedDate() {
329	        return issuedDate;
330	    }
331	
332	    public LocalDate getDueDate() {
333	        return dueDate;
334	    }
335	
336	    public List<InvoiceLineItem> getLineItems() {
337	        return List.copyOf(lineItems);
338	    }
339	
340	    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
341	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
342	        return addLineItem(description, qty, unit, unitPrice, false, BigDecimal.ZERO);
343	    }
344	
345	    /**
346	     * Adds a line, taxable or tax-free and with any discount of its own, to this invoice and reworks its
347	     * amount to include what the line charges after that discount.
348	     */
349	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
350	            boolean taxExempt, BigDecimal discountPct) {
351	        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt, discountPct);
352	        lineItems.add(item);
353	        recalculateAmount();
354	        return item;
355	    }
356	
357	    /** Changes one of this invoice's lines and reworks its amount to match. */
358	    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
359	            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct) {
360	        item.update(description, qty, unit, unitPrice, taxExempt, discountPct);
361	        recalculateAmount();
362	    }
363	
364	    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
365	    public void removeLineItem(InvoiceLineItem item) {
366	        lineItems.remove(item);
367	        recalculateAmount();
368	    }
369	
370	    /** The line on this invoice with the given id, if there is one. */
371	    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
372	        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
373	    }
374	
375	    /** Replaces this invoice's discounts with a single percentage and reworks its amount to match. */
376	    public void applyDiscount(BigDecimal discountPct) {
377	        applyDiscount(discountPct, BigDecimal.ZERO);
378	    }
379	
380	    /**
381	     * Replaces this invoice's discounts with a single one, either a percentage or a flat amount (the other
382	     * being zero; zero for both leaves no discount), and reworks its amount to match.
383	     */
384	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
385	        applyDiscount(discountPct, discountAmount, null);
386	    }
387	
388	    /**
389	     * Replaces this invoice's discounts with a single one, either a percentage (optionally capped at the
390	     * most it takes off) or a flat amount, and reworks its amount to match.
391	     */
392	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
393	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
394	        discounts.clear();
395	        if (discountPct.signum() != 0 || discountAmount.signum() != 0) {
396	            discounts.add(discount);
397	        }
398	        recalculateAmount();
399	    }
400	
401	    /**
402	     * Adds another discount to this invoice, either a percentage or a flat amount (the other being zero),
403	     * and reworks its amount to match.
404	     */
405	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
406	        return addDiscount(discountPct, discountAmount, null);
407	    }
408	
409	    /**
410	     * Adds another discount to this invoice, either a percentage (optionally capped at the most it takes
411	     * off) or a flat amount, and reworks its amount to match.
412	     */
413	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
414	        if (discountPct.signum() == 0 && discountAmount.signum() == 0) {
415	            throw new IllegalArgumentException("A discount takes off a percentage or a flat amount");
416	        }
417	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
418	        discounts.add(discount);
419	        recalculateAmount();
420	        return discount;
421	    }
422	
423	    /** Removes a discount from this invoice and reworks its amount to match. */
424	    public void removeDiscount(InvoiceDiscount discount) {
425	        discounts.remove(discount);
426	        recalculateAmount();
427	    }
428	
429	    /** The discount on this invoice with the given id, if there is one. */
430	    public Optional<InvoiceDiscount> findDiscount(Long discountId) {
431	        return discounts.stream().filter(d -> d.getId().equals(discountId)).findFirst();
432	    }
433	
434	    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
435	    public void applyTax(BigDecimal taxPct) {
436	        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
437	        recalculateAmount();
438	    }
439	
440	    /** Sets whether this invoice's prices already include tax and reworks its amount to match. */
441	    public void applyTaxInclusive(boolean taxInclusive) {
442	        this.taxInclusive = taxInclusive;
443	        recalculateAmount();
444	    }
445	
446	    /** Sets whether this invoice is for a tax-exempt client and reworks its amount to match. */
447	    public void applyTaxExempt(boolean taxExempt) {
448	        this.taxExempt = taxExempt;
449	        recalculateAmount();
450	    }
451	
452	    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
453	    public void applyLevy(BigDecimal levyPct) {
454	        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
455	        recalculateAmount();
456	    }
457	
458	    /** Sets the flat surcharge (such as a handling fee) added to this invoice and reworks its amount to match. */
459	    public void applySurcharge(BigDecimal surcharge) {
460	        this.surcharge = surcharge.setScale(2, RoundingMode.HALF_UP);
461	        recalculateAmount();
462	    }
463	
464	    /**
465	     * Sets the early-payment discount offered on this invoice: the percentage taken off if it is paid
466	     * within the given number of days of being issued. It does not change the amount owed.
467	     */
468	    public void applyEarlyPayment(BigDecimal earlyPaymentPct, int earlyPaymentDays) {
469	        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
470	        this.earlyPaymentDays = earlyPaymentDays;
471	    }
472	
473	    /**
474	     * The discount taken off one line, to the cent: the uncapped percentages together, plus its share of
475	     * what the flat amounts and the capped percentages take off in proportion to what the line charges
476	     * out of the subtotal.
477	     */
478	    private BigDecimal discountOn(BigDecimal line) {
479	        BigDecimal subtotal = getSubtotal();
480	        BigDecimal pct = percentOf(line, uncappedPct(subtotal));
481	        if (subtotal.signum() == 0) {
482	            return pct;
483	        }
484	        BigDecimal flatShare = sharedDiscount(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
485	        return pct.add(flatShare);
486	    }
487	
488	    /** The percentages not limited by a cap, added up (never more than 100). */
489	    private BigDecimal uncappedPct(BigDecimal subtotal) {
490	        return discounts.stream().filter(d -> d.isPercentage() && !isCappedAt(subtotal, d)).map(InvoiceDiscount::getDiscountPct)
491	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).min(BigDecimal.valueOf(100).setScale(2));
492	    }
493	
494	    /**
495	     * What the flat discounts and the capped percentages actually take off the subtotal together, shared
496	     * across the lines in proportion to what each charges.
497	     */
498	    private BigDecimal sharedDiscount(BigDecimal subtotal) {
499	        return discounts.stream().filter(d -> !d.isPercentage() || isCappedAt(subtotal, d)).map(this::discountTakenBy)
500	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
501	    }
502	
503	    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
504	    private BigDecimal taxOn(BigDecimal line) {
505	        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
506	    }
507	
508	    /** The levy on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
509	    private BigDecimal levyOn(BigDecimal line) {
510	        return taxInclusive ? includedIn(line, levyPct) : percentOf(line, levyPct);
511	    }
512	
513	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
514	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
515	    }
516	
517	    private void recalculateAmount() {
518	        BigDecimal subtotal = getSubtotal();
519	        BigDecimal discounted = subtotal.subtract(getDiscount());
520	        this.amount = (taxInclusive ? discounted : discounted.add(getTax()).add(getLevy())).add(surcharge);
521	    }
522	
523	    /** Marks this invoice as sent to the client. */
524	    public void markSent() {
525	        this.status = InvoiceStatus.SENT;
526	    }
527	
528	    /** Cancels this invoice, so it is no longer owed. */
529	    public void markVoid() {
530	        this.status = InvoiceStatus.VOID;
531	    }
532	
533	    /** What is left to pay on this invoice given the total paid against it; nothing once it is void. */
534	    public BigDecimal amountDue(BigDecimal paid) {
535	        return status == InvoiceStatus.VOID ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid);
536	    }
537	
538	    /**
539	     * Works out this sent invoice's status from the total paid against it: PAID once the payments
540	     * cover the amount, PARTIAL once something has been paid, otherwise still SENT.
541	     */
542	    public void applyPaidTotal(BigDecimal paid) {
543	        if (status == InvoiceStatus.DRAFT || status == InvoiceStatus.VOID) {
544	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be paid");
545	        }
546	        if (paid.compareTo(amount) >= 0) {
547	            this.status = InvoiceStatus.PAID;
548	        } else if (paid.signum() > 0) {
549	            this.status = InvoiceStatus.PARTIAL;
550	        } else {
551	            this.status = InvoiceStatus.SENT;
552	        }
553	    }
554	}
